// If lat/lon are set via env, skip Nominatim
const lat = env.get('WEATHER_LAT')
const lon = env.get('WEATHER_LON')
if (lat && lon) {
    flow.set('weather_lat', parseFloat(lat))
    flow.set('weather_lon', parseFloat(lon))
    const loc = env.get('WEATHER_LOCATION') || 'Unbekannt'
    flow.set('weather_location', loc)
    node.log('Using env coordinates: ' + lat + ',' + lon)
    return [null, msg]  // skip nominatim
}
const location = env.get('WEATHER_LOCATION') || 'Zürich'
flow.set('weather_location', location)
msg.url = 'https://nominatim.openstreetmap.org/search?q=' + encodeURIComponent(location) + '&format=json&limit=1'
msg.headers = { 'User-Agent': 'Home-Dashboard-RPi/1.0 (nodered)' }
return [msg, null]
